#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

string doAppearInSomeCell(const string& input) {
    if (input.length() < 3) {
        return "No";
    }

    vector<string> set = {"ABC", "ACB", "BAC", "BCA", "CAB", "CBA"};

    for (size_t i = 0; i + 3 <= input.length(); i++) {
        string k = input.substr(i, 3);
        if (find(set.begin(), set.end(), k) != set.end()) {
            return "Yes";
        }
    }

    return "No";
}

int main() {
    string input;
    getline(cin, input);
    cout << doAppearInSomeCell(input);
    return 0;
}
